def build(path):
    d=Document();sec=d.sections[0]
    sec.page_width=Cm(21.59);sec.page_height=Cm(27.94)
    sec.left_margin=sec.right_margin=Cm(3)
    for style in ['Normal','Title','Heading 1']:
        s=d.styles[style];s.font.name='Courier New';s.font.size=Pt(14)
        s.font.color.rgb=RGBColor.from_string('274766');s.paragraph_format.line_spacing=1.6
    d.styles['Heading 1'].font.size=Pt(18)
    for style,text in BLOCKS:
        if style=='TABLE':
            t=d.add_table(rows=0,cols=3);t.style='Table Grid'
            for row in text:
                for c,v in zip(t.add_row().cells,row):c.text=v
        else:d.add_paragraph(text,style)
    d.core_properties.author='';d.core_properties.title=TITLE
    path.parent.mkdir(parents=True,exist_ok=True);d.save(path)

if __name__=='__main__':
    import argparse
    p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args();build(a.output)
